CREATE TABLE IF NOT EXISTS {fq}.`gold_ebitda_forecast` (
  `state_code` STRING COMMENT 'US state code (2-letter) where circuits are deployed',
  `device_type` STRING COMMENT 'Copper equipment type: CPE, OLT, ONT, or Patch Panel',
  `risk_tier` STRING COMMENT 'ML model predicted risk tier (V5): critical, high, medium, low',
  `fiber_ready` BOOLEAN COMMENT 'Whether the wire center has fiber infrastructure ready for migration',
  `scenario` STRING COMMENT 'Forecast scenario: base (planned timeline), optimistic (1Q earlier), pessimistic (1Q later)',
  `quarter` STRING COMMENT 'Projected retirement quarter in YYYY-QN format',
  `forecast_revenue_at_risk` DOUBLE COMMENT 'Quarterly revenue at risk from circuits being retired in this quarter (annual / 4 * retire %)',
  `forecast_annual_revenue_exposure` DOUBLE COMMENT 'Full annual revenue exposure for circuits retiring in this quarter',
  `forecast_cost_savings` DOUBLE COMMENT 'Quarterly operating cost savings from decommissioning copper plant',
  `forecast_capex` DECIMAL(18,2) COMMENT 'One-time capital expenditure for fiber replacement in this quarter',
  `forecast_net_benefit` DOUBLE COMMENT 'Net quarterly benefit: cost savings minus amortized capex (5yr / 20Q)',
  `forecast_ebitda_impact` DOUBLE COMMENT 'Total quarterly EBITDA impact: savings + 15% avoided maintenance - amortized capex',
  `circuit_count` BIGINT COMMENT 'Number of circuits projected to retire in this state/device/risk/quarter combination',
  `avg_risk_score` DOUBLE COMMENT 'Average ML composite risk score for circuits in this group',
  `forecast_generated_at` TIMESTAMP COMMENT 'Timestamp when this forecast was generated'
) USING DELTA
COMMENT 'SYNTHETIC DATA — Projected quarterly EBITDA impact from Lakelink Fiber copper retirement program. Three scenarios (base/optimistic/pessimistic) model retirement timelines by ML risk tier. Each row is one state × device_type × risk_tier × fiber_ready × scenario × quarter combination. Source: gold_circuit_revenue_at_risk (14,777 circuits). Generated by @data-analyst.'
